local t, ns = ...
local Engine, Ledger, Tables, Sha256 = ns.Engine, ns.Ledger, ns.Tables, ns.Sha256

-- Checks Engine and Ledger against tests/vectors.lua, generated by the independent Python
-- reference in tools/ref/. Skipped (one passing test) when the file is absent.

local fh = io.open("tests/vectors.lua")
if not fh then
	t.test("vectors.lua not present", function() end)
	return
end
fh:close()

local V = t.load("vectors.lua")
local E, L = V.engine or {}, V.ledger or {}
local T1 = Tables.get("T1")

local function each(group, name, fn)
	t.test(name .. " (" .. #(group or {}) .. " vectors)", function()
		t.ok(group and #group > 0, "group " .. name .. " is empty or missing")
		for i, v in ipairs(group) do fn(v, name .. "[" .. i .. "]") end
	end)
end

each(E.keys, "engine.keys", function(v, at)
	t.eq(Engine.commit(v.seed), v.commit, at .. " commit")
	t.eq(Engine.purchaseKey(v.buyId, v.seed, v.nonce), v.K, at .. " K")
end)

each(E.witness, "engine.witness", function(v, at)
	t.eq(Engine.witnessValue(v.S, v.player, v.kind, v.n, v.g, v.amount, v.head), v.value, at)
end)

each(E.lots, "engine.lots", function(v, at)
	t.eq(Engine.lot(v.witness, v.player, v.kind, v.n, v.g), v.lot, at)
end)

each(E.drawn, "engine.drawn", function(v, at)
	t.eq(Engine.drawn(v.lot, v.A, v.Z), v.drawn, at)
end)

each(E.contribs, "engine.contribs", function(v, at)
	t.eq(Engine.contribs(v.list), v.text, at)
end)

each(E.spins, "engine.spins", function(v, at)
	local s1, s2, s3 = Engine.spin(v.K, v.n, v.contribs, T1)
	t.eq(s1, v.s1, at .. " s1") t.eq(s2, v.s2, at .. " s2") t.eq(s3, v.s3, at .. " s3")
	if v.multiplier ~= nil then
		t.eq(Tables.multiplier(T1, s1, s2, s3), v.multiplier, at .. " multiplier")
	end
	-- The keyed form gives the same stops.
	local k1, k2, k3 = Engine.spin(Sha256.keyed(v.K), v.n, v.contribs, T1)
	t.ok(k1 == s1 and k2 == s2 and k3 == s3, at .. " keyed")
end)

each(E.gambles, "engine.gambles", function(v, at)
	t.eq(Engine.gamble(v.K, v.n, v.g, v.contribs), v.won, at)
end)

local function decodeAll(entries, at)
	local out = {}
	for i, text in ipairs(entries) do
		if type(text) == "string" then
			local e, code = Ledger.decode(text)
			t.ok(e, at .. " entry " .. i .. " decodes: " .. tostring(code))
			t.eq(Ledger.encode(e), text, at .. " entry " .. i .. " canonical")
			out[i] = e
		else
			out[i] = text
		end
	end
	return out
end

local STEP_FIELDS = { "type", "balance", "pending", "multiplier", "win", "won" }

each(L.accounts, "ledger.accounts", function(v, at)
	at = at .. (v.name and (" " .. v.name) or "")
	local entries = decodeAll(v.entries, at)
	local st = Ledger.start(v.guild, v.player)
	if v.h0 then t.eq(st.head, v.h0, at .. " h0") end
	for i, e in ipairs(entries) do
		local info, code = Ledger.apply(st, e)
		t.ok(info, at .. " entry " .. i .. " applies: " .. tostring(code))
		if v.heads and v.heads[i] then
			t.eq(Ledger.shortHead(st), v.heads[i], at .. " head " .. i)
		end
		local want = v.steps and v.steps[i]
		if want then
			for _, f in ipairs(STEP_FIELDS) do
				if want[f] ~= nil then t.eq(info[f], want[f], at .. " step " .. i .. " " .. f) end
			end
			if want.stops then
				for r = 1, 3 do t.eq(info.stops[r], want.stops[r], at .. " step " .. i .. " stop " .. r) end
			end
		end
	end
	for k, want in pairs(v.final or {}) do
		t.eq(st[k], want, at .. " final " .. k)
	end
	-- replay gives the same result.
	local r = Ledger.replay(v.guild, v.player, v.entries)
	t.ok(r, at .. " replay")
	t.eq(r.head, st.head, at .. " replay head")
end)

local function checkInvalid(v, at)
	at = at .. (v.note and (" (" .. v.note .. ")") or "")
	local st, code, index = Ledger.replay(v.guild, v.player, v.entries)
	t.eq(st, nil, at .. " must fail")
	t.eq(code, v.code, at .. " code")
	t.eq(index, v.index, at .. " index")
end

each(L.invalid, "ledger.invalid", checkInvalid)
if L.ambiguous then each(L.ambiguous, "ledger.ambiguous", checkInvalid) end

each(L.decode_bad, "ledger.decode_bad", function(v, at)
	local text, want = v, "bad_entry"
	if type(v) == "table" then
		text, want = v.text, v.code or "bad_entry"
		at = at .. (v.note and (" (" .. v.note .. ")") or "")
	end
	local e, code = Ledger.decode(text)
	t.eq(e, nil, at .. " must fail")
	t.eq(code, want, at .. " code")
end)
